onClick:
{{
  (async () => {
    try {
      // CAS 1 : Une facture est sélectionnée dans la liste -> Compensation
      if (sel_facture_a_compenser.selectedOptionValue) {
        await Compenser_Avoir_Facture.run();
        showAlert('Avoir imputé avec succès sur la facture !', 'success');
      } 
      // CAS 2 : Pas de facture liée -> Remboursement (Espèces, Virement...) ou encaissement classique
      else {
        if (!radio_mode_paiement.selectedOptionValue) {
          showAlert('Veuillez sélectionner un mode de paiement', 'warning');
          return;
        }
        await Insert_Reglement.run();
        showAlert('Règlement enregistré avec succès !', 'success');
      }

      // Rechargement des factures et fermeture de la modale
      await Get_BL_Factures.run();
      closeModal('modal_add_reglement');

    } catch (err) {
      showAlert("Erreur lors de l'enregistrement : " + err.message, 'error');
    }
  })()
}}
